package com.bank.reference;

import java.util.logging.Logger;

// Validates numeric transfer reference codes at National Bank of India.
public class ReferenceCodeValidator {
    private static final Logger log = Logger.getLogger(ReferenceCodeValidator.class.getName());

    // Returns true if the digits of the code read the same both ways.
    public boolean isPalindrome(long code) {
        if (code < 0) {
            // Negative codes never palindrome: the sign cannot mirror.
            log.fine(() -> "Rejecting negative code " + code);
            return false;
        }
        long original = code;
        long reversed = 0;          // long accumulator guards against int overflow
        while (code > 0) {
            long lastDigit = code % 10;        // peel last digit
            reversed = reversed * 10 + lastDigit; // shift left, append
            code = code / 10;                  // drop last digit
        }
        boolean result = reversed == original;
        log.fine(() -> "Code " + original + " reversed to " + reversed + " palindrome=" + result);
        return result;
    }

    // Counts how many codes in the batch are palindromic.
    public int countPalindromes(long[] codes) {
        int count = 0;
        for (long c : codes) {
            if (isPalindrome(c)) {
                count++;
            }
        }
        log.info(() -> "Palindrome count in batch of " + codes.length + " = " + count);
        return count;
    }
}
