package com.bank.reference;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: issue transfer reference codes and validate them.
public class ReferenceDemo {
    private static final Logger log = Logger.getLogger(ReferenceDemo.class.getName());

    static {
        // Clean single-line log setup for the demo.
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ReferenceCodeValidator validator = new ReferenceCodeValidator();

        // Rajesh (SAV2001) transfer reference, Priya (CUR3001) transfer reference.
        long rajeshCode = 1221L;   // palindrome
        long priyaCode  = 12345L;  // not a palindrome

        log.info(() -> "Rajesh code " + rajeshCode + " palindrome? " + validator.isPalindrome(rajeshCode));
        log.info(() -> "Priya code " + priyaCode + " palindrome? " + validator.isPalindrome(priyaCode));

        long[] batch = {1221L, 12321L, 100L, 555L, 12345L};
        int palindromes = validator.countPalindromes(batch);
        log.info(() -> "End-of-day quality metric: " + palindromes + " palindromic codes in today's batch");
    }
}
